      "rank": 1,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Giovanni Gallavotti"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation theorems supplied an exceptionally clear, general law for far-from-equilibrium physics, changing how work, dissipation, and irreversibility can be quantified.",
        "attribution": "Evans and Gallavotti established seminal fluctuation relations, while Jarzynski gave the central equality connecting nonequilibrium work to equilibrium free energies.",
        "maturity": "The relations are theoretically well understood, broadly tested, and used across molecular, soft-matter, and quantum systems.",
        "uncertainties": [
          "The linked developments comprise several closely related theorems, so defining one prize-worthy formulation requires care."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B044",
      "proposed_laureates": [
        "John Toner",
        "Sriram Ramaswamy",
        "Tamás Vicsek"
      ],
      "assessment": {
        "nobel_worthiness": "The theory of collective active motion revealed robust nonequilibrium order and hydrodynamics in systems from flocks to synthetic active matter.",
        "attribution": "Vicsek introduced a decisive minimal model, and Toner and Ramaswamy developed the theoretical framework explaining its collective physics.",
        "maturity": "The field has matured through extensive experiments, simulations, and theoretical extensions over decades.",
        "uncertainties": [
          "The experimental manifestations span diverse systems whose relation to idealized hydrodynamic models is not always direct."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electron problems quantitatively tractable and established a powerful conceptual account of the Mott transition.",
        "attribution": "Vollhardt and collaborators developed the large-dimensional foundation, while Georges and Kotliar made the method into a broadly usable framework.",
        "maturity": "It is a deeply established method with wide predictive and interpretive influence in correlated materials.",
        "uncertainties": [
          "Credit is distributed across foundational formal work and later methodological development."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction identified the mechanism by which fragile quantum information can be protected, making scalable quantum computation physically conceivable.",
        "attribution": "Shor and Steane introduced seminal code constructions, and Kitaev supplied foundational fault-tolerant and topological ideas.",
        "maturity": "The principles are firmly established and increasingly demonstrated in hardware, though fully fault-tolerant machines remain incomplete.",
        "uncertainties": [
          "The eventual practical scale and architecture of fault-tolerant quantum computing remain unsettled."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric quantum phases exposed a fundamental, observable role of global phase structure and have become central to modern quantum and topological physics.",
        "attribution": "Berry gave the adiabatic geometric-phase formulation, and Aharonov's earlier work established the physical significance of quantum phases and potentials.",
        "maturity": "The effects are experimentally secure and have generated enduring consequences across quantum physics.",
        "uncertainties": [
          "The relationship between the Aharonov-Bohm effect and Berry phase is conceptually close but not a single historical discovery."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Alexander A. Belavin",
        "Alexander B. Zamolodchikov",
        "Alexander M. Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Two-dimensional conformal field theory provided an exact and extraordinarily generative framework connecting critical statistical systems with quantum field theory.",
        "attribution": "Belavin, Polyakov, and Zamolodchikov established the decisive symmetry-based solution and its operator structure.",
        "maturity": "Its mathematical and physical importance has been sustained for decades, including in critical phenomena and string theory.",
        "uncertainties": [
          "Its most direct experimental consequences are less sharply isolable than those of some other candidates."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Anthony A. Hyman",
        "Clifford P. Brangwynne",
        "Frank Jülicher"
      ],
      "assessment": {
        "nobel_worthiness": "Biomolecular condensates brought phase separation and nonequilibrium physics into a compelling account of intracellular organization.",
        "attribution": "Hyman and Brangwynne provided pioneering biological observations and concepts, while Jülicher supplied major physical theory of active cellular condensates.",
        "maturity": "The phenomenon is broadly documented and has reshaped cell biophysics, although its mechanistic diversity is still being resolved.",
        "uncertainties": [
          "Whether condensate language identifies a sufficiently universal causal mechanism across cellular contexts remains under active examination."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their foundational proposals supplied a coherent physical route to quantum computation and simulation with controllable atomic systems.",
        "attribution": "Cirac and Zoller jointly made seminal proposals that connected quantum-information concepts to realizable atomic platforms.",
        "maturity": "Atomic quantum simulation is now a powerful experimental reality, with continued growth in quantum-computing capability.",
        "uncertainties": [
          "The broad platform's later success involved many experimental and theoretical contributors beyond the named pair."
        ]
      }
    }
  ]
